const {chromium}=require('/Users/allanbranch/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');const assert=require('node:assert/strict'),d=require('../docs/finance-dashboard.json'),c=require('../docs/cpi-benchmark.json');const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
(async()=>{const b=await chromium.launch({channel:'chrome',headless:true});try{const p=await b.newPage();const errors=[];p.on('pageerror',e=>errors.push(e.message));for(const route of ['','public-safety-preview.html'])for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:900});await p.goto((process.env.PCARDS_TEST_URL||'http://localhost:4398/')+route);await p.locator('.finance-group').first().waitFor();for(const a of d.departments){const card=p.locator(`[data-comparison-id="${a.id}"]`),base=a.points.find(q=>q.year===2017&&q.value!==null),now=a.points.find(q=>q.year===2027&&q.value!==null);assert.equal(await card.locator('.expense-dashboard-total').textContent(),now?money(now.value):'Not available');if(base&&base.basis==='Actual'){const expected=base.value*c.projection.values[2027]/c.values[2017];assert((await card.locator('.finance-inflation').textContent()).includes(money(expected)));assert.equal(await card.locator('.cpi-projected.cpi-point').count(),2);}else assert((await card.locator('.finance-inflation').textContent()).includes('Unavailable'));}const police=p.locator('[data-comparison-id="001-2100"]');assert((await police.locator('.finance-line svg').getAttribute('aria-label')).includes('2012: $9,938,086'));for(const year of [2017,2025,2026,2027]){const hit=police.locator(`[data-year="${year}"]`);await hit.scrollIntoViewIfNeeded();await hit.hover();const tip=p.getByRole('tooltip');assert((await tip.innerText()).includes(String(year)));assert.equal((await tip.innerText()).includes('Projected inflation benchmark'),year>2025);const box=await tip.boundingBox();assert(box.x>=0&&box.x+box.width<=width);await hit.focus();assert(await tip.isVisible());await p.keyboard.press('Escape');assert(await tip.isHidden());}await p.getByRole('button',{name:'Revenue & tax rates',exact:true}).click();assert.equal(await p.locator('.cpi-point').count(),0);const merchant=p.locator('[data-comparison-id="316.100"]');assert((await merchant.locator('.finance-line svg').getAttribute('aria-label')).includes('2012: $7,307,619'));assert.equal(await p.locator('[data-comparison-id="311.100"] .finance-card-title').innerText(),'Property taxes');assert(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));console.log('PASS historical data, all department inflation amounts, tooltips and layout',route||'home',width);}assert.deepEqual(errors,[]);const touch=await b.newPage({viewport:{width:390,height:844},isMobile:true,hasTouch:true});await touch.goto((process.env.PCARDS_TEST_URL||'http://localhost:4398/'));await touch.locator('[data-comparison-id="001-2100"] [data-year="2027"]').tap();assert(await touch.getByRole('tooltip').isVisible());await touch.locator('#expense-dashboard h2').tap();assert(await touch.getByRole('tooltip').isHidden());console.log('PASS touch and outside dismissal');}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
